import { useMemo } from 'react'
import { useQuery } from '@tanstack/react-query'
import type { RdeDataset, RdeNumericKey, RdeOperatingPoint, RdePublication, RdeRelease } from '../types/rde'
import { ENGINE_LABELS, NO_VALUE, codeLabel, isRdeNumericKey, rdeValue } from '../lib/rdeFields'
import { listValues, numberParam } from '../components/filters'
import { downloadText, toCsv } from '../lib/csv'

// The RDE operating points are one static file, generated by
// scripts/build_data.py from data/rde_subset/ and served next to index.html.
export async function loadRde(): Promise<RdeDataset> {
  const res = await fetch(`${import.meta.env.BASE_URL}rde.json`)
  if (!res.ok) throw new Error(`Could not load rde.json (HTTP ${res.status})`)
  return res.json() as Promise<RdeDataset>
}

/** Loaded once per visit and kept, like the cell-size cases. */
export function useRde() {
  // One retry: the cell-size pages wait for it only for the RDE tab count.
  return useQuery({ queryKey: ['rde'], queryFn: loadRde, staleTime: Infinity, gcTime: Infinity, retry: 1 })
}

/** Publications by id. */
export function publicationIndex(data: RdeDataset): Map<number, RdePublication> {
  return new Map(data.publications.map(p => [p.id, p]))
}

// Filters ---------------------------------------------------------------------
//
// The URL carries the filters, as on the cell-size pages. fuel, oxidizer, q and
// equivalence_ratio_min/max use the same names there, so they carry over when
// switching category.

export interface RdeFacet {
  param: string
  label: string
  /** The facet value of a point. */
  value: (p: RdeOperatingPoint) => string
  /** How a value is shown. */
  display: (value: string, pubs: Map<number, RdePublication>) => string
}

export const NOT_REPORTED = 'none'

export const RDE_FACETS: RdeFacet[] = [
  { param: 'engine', label: 'Engine class', value: p => p.engine_code, display: v => ENGINE_LABELS[v as keyof typeof ENGINE_LABELS] ?? v },
  { param: 'fuel', label: 'Fuel', value: p => p.fuel, display: v => v },
  { param: 'oxidizer', label: 'Oxidizer', value: p => p.oxidizer, display: v => v.replace('O2', 'O₂') },
  {
    param: 'waves',
    label: 'Waves (primary direction)',
    value: p => (p.wave_count != null ? String(p.wave_count) : NOT_REPORTED),
    display: v => (v === NOT_REPORTED ? NO_VALUE : v),
  },
  { param: 'combustor', label: 'Combustor', value: p => p.combustor_type ?? 'unspecified', display: v => codeLabel(v) },
  { param: 'op_type', label: 'Operating point', value: p => p.operating_point_type, display: v => codeLabel(v) },
  {
    param: 'publication',
    label: 'Publication',
    value: p => String(p.publication_id),
    display: (v, pubs) => pubs.get(Number(v))?.label ?? `Publication ${v}`,
  },
]

/** "Has a value for": every ticked measurement must be present (AND). */
export interface RdeMeasure {
  value: string
  label: string
  test: (p: RdeOperatingPoint) => boolean
}

export const RDE_MEASURES: RdeMeasure[] = [
  { value: 'wave_count', label: 'Number of waves', test: p => p.wave_count != null },
  { value: 'secondary_waves', label: 'Secondary-direction waves', test: p => p.secondary_wave_count != null },
  { value: 'wave_speed', label: 'Wave speed', test: p => p.wave_speed_m_s != null },
  { value: 'frequency', label: 'Operating frequency', test: p => p.frequency_khz != null },
  { value: 'thrust', label: 'Thrust', test: p => p.thrust_n != null },
  { value: 'isp', label: 'Specific impulse', test: p => p.specific_impulse_s != null },
  { value: 'chamber_pressure', label: 'Chamber pressure', test: p => (p.chamber_pressures?.length ?? 0) > 0 },
  { value: 'pressure_gain', label: 'Pressure gain', test: p => p.pressure_gain_percent != null },
]

export interface RdeRange {
  /** URL parameters are `${param}_min` and `${param}_max`. */
  param: string
  field: RdeNumericKey
  label: string
  unit: string
}

export const RDE_RANGES: RdeRange[] = [
  { param: 'equivalence_ratio', field: 'equivalence_ratio', label: 'φ', unit: '' },
  { param: 'mdot_total', field: 'mdot_total_kg_s', label: 'ṁ total', unit: 'kg/s' },
  { param: 'chamber_od', field: 'chamber_outer_diameter_mm', label: 'Chamber OD', unit: 'mm' },
]

export interface RdeFilters {
  q: string
  /** Selected values per facet param; a facet with none selected does not filter. */
  lists: Record<string, string[]>
  has: string[]
  ranges: Record<string, { min?: number; max?: number }>
}

export function parseRdeFilters(params: URLSearchParams): RdeFilters {
  const lists: Record<string, string[]> = {}
  for (const f of RDE_FACETS) lists[f.param] = [...new Set(listValues(params, f.param))]
  const ranges: Record<string, { min?: number; max?: number }> = {}
  for (const r of RDE_RANGES) {
    const min = numberParam(params, `${r.param}_min`)
    const max = numberParam(params, `${r.param}_max`)
    if (min != null || max != null) ranges[r.param] = { min, max }
  }
  return {
    q: params.get('q')?.trim() ?? '',
    lists,
    has: [...new Set(listValues(params, 'has'))].filter(v => RDE_MEASURES.some(m => m.value === v)),
    ranges,
  }
}

/** Number of active RDE filters in the URL. */
export function countRdeFilters(params: URLSearchParams): number {
  const f = parseRdeFilters(params)
  let n = f.q ? 1 : 0
  for (const values of Object.values(f.lists)) n += values.length
  n += f.has.length
  for (const r of Object.values(f.ranges)) n += (r.min != null ? 1 : 0) + (r.max != null ? 1 : 0)
  return n
}

/** A copy of the params with every RDE filter removed (view, sort and plot kept). */
export function clearRdeFilters(params: URLSearchParams): URLSearchParams {
  const next = new URLSearchParams(params)
  next.delete('q')
  next.delete('has')
  for (const f of RDE_FACETS) next.delete(f.param)
  for (const r of RDE_RANGES) {
    next.delete(`${r.param}_min`)
    next.delete(`${r.param}_max`)
  }
  next.delete('offset')
  return next
}

/** Lower case with subscript digits folded, so "O₂" finds "O2". */
function fold(s: string): string {
  return s.toLowerCase().replace(/[₀-₉]/g, c => String(c.charCodeAt(0) - 0x2080))
}

function searchText(p: RdeOperatingPoint, pub: RdePublication | undefined): string {
  return fold([
    p.fuel, p.fuel_reported, p.oxidizer, p.oxidizer_reported, ENGINE_LABELS[p.engine_code],
    pub?.label, pub?.title, pub?.authors, pub?.venue, pub?.doi, pub?.country,
  ].filter(Boolean).join(' '))
}

/** Every term must match: "#12" is operating point 12 exactly, anything else
 *  a substring of the point's text. */
function matchesSearch(p: RdeOperatingPoint, pub: RdePublication | undefined, q: string): boolean {
  const text = searchText(p, pub)
  return fold(q).split(/\s+/).every(term => {
    const id = /^#(\d+)$/.exec(term)
    return id ? p.id === Number(id[1]) : text.includes(term)
  })
}

/** Whether a point passes the filters, ignoring the facet named in `except`
 *  (used to count the options of that facet). */
export function matchesRde(
  p: RdeOperatingPoint,
  f: RdeFilters,
  pubs: Map<number, RdePublication>,
  except?: string,
): boolean {
  if (f.q && !matchesSearch(p, pubs.get(p.publication_id), f.q)) return false
  for (const facet of RDE_FACETS) {
    if (facet.param === except) continue
    const selected = f.lists[facet.param]
    if (selected && selected.length > 0 && !selected.includes(facet.value(p))) return false
  }
  if (except !== 'has') {
    for (const value of f.has) {
      const m = RDE_MEASURES.find(x => x.value === value)
      if (m && !m.test(p)) return false
    }
  }
  for (const r of RDE_RANGES) {
    const range = f.ranges[r.param]
    if (!range) continue
    const v = rdeValue(p, r.field)
    if (v == null) return false
    if (range.min != null && v < range.min) return false
    if (range.max != null && v > range.max) return false
  }
  return true
}

export function filterRde(data: RdeDataset, f: RdeFilters): RdeOperatingPoint[] {
  const pubs = publicationIndex(data)
  return data.operating_points.filter(p => matchesRde(p, f, pubs))
}

export interface RdeOption {
  value: string
  label: string
  /** Points that would match if this value were ticked, given the other filters. */
  count: number
}

const collator = new Intl.Collator('en', { numeric: true, sensitivity: 'base' })

/** The options of one facet, with counts under the other active filters.
 *  Every value in the data is listed, selected ones even at a count of zero. */
export function facetOptions(data: RdeDataset, f: RdeFilters, facet: RdeFacet): RdeOption[] {
  const pubs = publicationIndex(data)
  const counts = new Map<string, number>()
  for (const p of data.operating_points) {
    const v = facet.value(p)
    if (!counts.has(v)) counts.set(v, 0)
    if (matchesRde(p, f, pubs, facet.param)) counts.set(v, (counts.get(v) ?? 0) + 1)
  }
  // A selected value the data lacks (carried over from the cell-size tab, or
  // an old link) is listed too, so it can be unticked.
  for (const v of f.lists[facet.param] ?? []) if (!counts.has(v)) counts.set(v, 0)
  const options = Array.from(counts, ([value, count]) => ({ value, label: facet.display(value, pubs), count }))
  if (facet.param === 'waves') {
    // 1, 2, 3 … then "not reported".
    return options.sort((a, b) => (a.value === NOT_REPORTED ? 1 : b.value === NOT_REPORTED ? -1 : Number(a.value) - Number(b.value)))
  }
  if (facet.param === 'publication') {
    return options.sort((a, b) => {
      const pa = pubs.get(Number(a.value)), pb = pubs.get(Number(b.value))
      return (pa?.year ?? 0) - (pb?.year ?? 0) || collator.compare(a.label, b.label)
    })
  }
  return options.sort((a, b) => b.count - a.count || collator.compare(a.label, b.label))
}

/** Counts for the "has a value for" checkboxes, under the other filters. */
export function measureOptions(data: RdeDataset, f: RdeFilters): RdeOption[] {
  const pubs = publicationIndex(data)
  const base = data.operating_points.filter(p => matchesRde(p, f, pubs, 'has'))
  return RDE_MEASURES.map(m => {
    const others = f.has.filter(v => v !== m.value)
    const count = base.filter(p => m.test(p) && others.every(v => RDE_MEASURES.find(x => x.value === v)?.test(p) ?? true)).length
    return { value: m.value, label: m.label, count }
  })
}

// Sorting ---------------------------------------------------------------------

export const RDE_DEFAULT_SORT = { by: 'publication', dir: 'asc' as const }

/** Sort by a numeric field, or by 'publication' (year, then paper, then the
 *  point's test run and its place in that run). Empty values sort last in both
 *  directions. */
export function sortRde(
  points: RdeOperatingPoint[],
  pubs: Map<number, RdePublication>,
  sortBy: string | null | undefined,
  sortDir: string | null | undefined,
): RdeOperatingPoint[] {
  const sign = sortDir === 'desc' ? -1 : 1
  const byPublication = (a: RdeOperatingPoint, b: RdeOperatingPoint) => {
    const pa = pubs.get(a.publication_id), pb = pubs.get(b.publication_id)
    return (pa?.year ?? 0) - (pb?.year ?? 0)
      || collator.compare(pa?.label ?? '', pb?.label ?? '')
      || a.publication_id - b.publication_id
      || a.test_run_id - b.test_run_id
      || (a.sequence_index ?? 0) - (b.sequence_index ?? 0)
      || a.id - b.id
  }
  if (!isRdeNumericKey(sortBy)) {
    return [...points].sort((a, b) => sign * byPublication(a, b))
  }
  return [...points].sort((a, b) => {
    const va = rdeValue(a, sortBy), vb = rdeValue(b, sortBy)
    if (va == null && vb == null) return byPublication(a, b)
    if (va == null) return 1
    if (vb == null) return -1
    return sign * (va - vb) || byPublication(a, b)
  })
}

// Hooks -----------------------------------------------------------------------

export interface RdeStats {
  operatingPoints: number
  publications: number
  fuels: number
  withWaveSpeed: number
  withWaveCount: number
  withThrust: number
}

export function useRdeStats(): { data: RdeStats | undefined } {
  const rde = useRde()
  const data = useMemo(() => {
    if (!rde.data) return undefined
    const points = rde.data.operating_points
    return {
      operatingPoints: points.length,
      publications: rde.data.publications.length,
      fuels: new Set(points.map(p => p.fuel)).size,
      withWaveSpeed: points.filter(p => p.wave_speed_m_s != null).length,
      withWaveCount: points.filter(p => p.wave_count != null).length,
      withThrust: points.filter(p => p.thrust_n != null).length,
    }
  }, [rde.data])
  return { data }
}

