/** The release version is on every row: operating point numbers are local to
 *  a release. Chamber pressures, several per point, are joined with ';'. */
export function rdeCsv(points: RdeOperatingPoint[], pubs: Map<number, RdePublication>, release: RdeRelease | null): string {
  const rows = points.map(p => {
    const pub = pubs.get(p.publication_id)
    const pressures = (p.chamber_pressures ?? []).map(c => c.pressure_kpa).filter(v => v != null)
    return {
      ...p,
      publication: pub?.label,
      doi: pub?.doi,
      release_version: release?.release_version,
      chamber_pressures_kpa: pressures.length ? pressures.join(';') : null,
    } as Record<string, unknown>
  })
  return toCsv(rows, [...RDE_CSV_COLUMNS])
}

export function downloadRdeCsv(
  points: RdeOperatingPoint[],
  pubs: Map<number, RdePublication>,
  release: RdeRelease | null,
  filename: string,
): void {
  downloadText(rdeCsv(points, pubs, release), filename, 'text/csv')
}
